import pandas as pd
import numpy as np

def transform_data(df1):
    # Calculate missing count per column
    missing_counts = df1.isnull().sum()
    total_rows = len(df1)
    # Build dataframe with required fields
    transformed_df = pd.DataFrame({
        "column": missing_counts.index,
        "missing_count": missing_counts.values,
        "missing_percent": (missing_counts.values / total_rows * 100).round(2)
    })
    # Define suggested action based on missing percentage
    def suggest_action(pct):
        if pct == 0:
            return "keep"
        elif pct < 5:
            return "impute"
        else:
            return "consider dropping or advanced imputation"
    transformed_df["suggested_action"] = transformed_df["missing_percent"].apply(suggest_action)
    return transformed_df
